static const char LIB_FS[] = "// std.fs " "\xe2" "\x80" "\x94" " Operaciones nativas del sistema de archivos via FFI\n// Integrante de la Biblioteca Estandar de Synapse.\n//\n// Uso desde Synapse:\n//   importar std.fs\n//   a = abrir_archivo(\"test.txt\", \"w\")\n//   escribir_archivo(a, \"hola mundo\")\n//   cerrar_archivo(a)\n//\n// Nota: Los handles de archivo se almacenan como enteros opacos.\n//       La implementacion subyacente usa FILE* de C.\n\nimportar_c \"<stdio.h>\"\n\n// Tipo envoltorio para FILE* de C (almacenado como entero opaco)\nestructura Archivo:\n    handle: entero\n\n// Declaraciones externas de C standard library\nexterno funcion fopen(ruta: char*, modo: char*) -> entero\nexterno funcion fclose(archivo: entero) -> entero\nexterno funcion fputs(str: char*, archivo: entero) -> entero\n\n// Wrappers nativos en Synapse\n\nfuncion abrir_archivo(ruta: texto, modo: texto) -> Archivo:\n    a = Archivo()\n    a.handle = fopen(ruta, modo)\n    retornar a\n\nfuncion cerrar_archivo(a: Archivo) -> entero:\n    retornar fclose(a.handle)\n\nfuncion escribir_archivo(a: Archivo, contenido: texto) -> entero:\n    retornar fputs(contenido, a.handle)\n";

static const char LIB_SYS[] = "// std.sys " "\xe2" "\x80" "\x94" " Operaciones del sistema operativo via FFI\n// Integrante de la Biblioteca Estandar de Synapse.\n//\n// Uso desde Synapse:\n//   importar std.sys\n//   salir(0)\n\nimportar_c \"<stdlib.h>\"\n\n// Declaracion externa de la funcion exit(3) de C standard library\nexterno funcion exit(codigo: entero) -> nulo\n\n// Envoltorio nativo: finaliza el programa con un codigo de salida\nfuncion salir(codigo: entero) -> nulo:\n    exit(codigo)\n";

static const char LIB_MODELO[] = "#lang: es\n// std.modelo " "\xe2" "\x80" "\x94" " Inferencia de modelos de lenguaje locales (transformers GGUF)\n// Integrante de la Biblioteca Estandar de Synapse.\n//\n// Arquitectura:\n//   - Carga segura de pesos GGUF via memory-mapped I/O\n//   - Gesti" "\xc3" "\xb3" "n determinista de memoria (sin GC)\n//   - Zero-telemetry: inferencia completamente local\n//   - BPE tokenizer integrado\n//   - KV cache optimizada para inferencia autoregresiva\n//\n// Uso desde Synapse:\n//   importar std.modelo\n//   ctx = cargar_modelo(\"modelo.gguf\")\n//   si ctx != nulo:\n//       logits = evaluar(ctx, token_id)\n//       token = argmax(logits)\n//       texto = decodificar_token(ctx, token)\n//       // O directamente:\n//       respuesta = generar_texto(ctx, \"Hola mundo\", 100, 0.7, 40, 0.9)\n//   cerrar_modelo(ctx)\n\n// ============================================================\n// Declaraciones externas (implementadas en synapse_rt.c)\n// ============================================================\n\n// --- Carga y ciclo de vida ---\nexterno funcion _syn_modelo_cargar(ruta: texto) -> puntero\nexterno funcion _syn_modelo_cerrar(ctx: puntero) -> nulo\n\n// --- Evaluaci" "\xc3" "\xb3" "n e inferencia token a token ---\nexterno funcion _syn_modelo_evaluar(ctx: puntero, token_id: entero) -> tensor\nexterno funcion _syn_modelo_generar(ctx: puntero, token_id: entero,\n    temperatura: decimal, top_k: entero, top_p: decimal) -> entero\n\n// --- Contexto (n_past, max_seq_len) ---\nexterno funcion _syn_modelo_n_past(ctx: puntero) -> entero\nexterno funcion _syn_modelo_reiniciar(ctx: puntero) -> nulo\nexterno funcion _syn_modelo_obtener_n_ctx(ctx: puntero) -> entero\nexterno funcion _syn_modelo_establecer_n_ctx(ctx: puntero, max_tokens: entero) -> nulo\n\n// --- Tokenizaci" "\xc3" "\xb3" "n ---\nexterno funcion _syn_modelo_decodificar_token(ctx: puntero, token_id: entero) -> texto\nexterno funcion _syn_modelo_vocab_tamano(ctx: puntero) -> entero\nexterno funcion _syn_modelo_codificar_contar(ctx: puntero, texto: texto) -> entero\nexterno funcion _syn_modelo_codificar_obtener(ctx: puntero, indice: entero) -> entero\n\n// --- Generaci" "\xc3" "\xb3" "n de texto de alto nivel ---\n// Procesa un prompt completo y genera texto autoregresivamente\nexterno funcion _syn_modelo_generar_texto(ctx: puntero, prompt: texto,\n    max_tokens: entero, temperatura: decimal, top_k: entero, top_p: decimal) -> texto\n\n// --- Metadatos del modelo ---\nexterno funcion _syn_modelo_obtener_metadato(ctx: puntero, clave: texto) -> texto\nexterno funcion _syn_modelo_obtener_arquitectura(ctx: puntero) -> texto\nexterno funcion _syn_modelo_obtener_n_layers(ctx: puntero) -> entero\nexterno funcion _syn_modelo_obtener_n_embd(ctx: puntero) -> entero\nexterno funcion _syn_modelo_obtener_n_heads(ctx: puntero) -> entero\n\n// ============================================================\n// Wrappers p" "\xc3" "\xba" "blicos (Synapse idiom" "\xc3" "\xa1" "tico)\n// ============================================================\n\n// --- Carga y ciclo de vida ---\n\nfuncion cargar_modelo(ruta: texto) -> puntero:\n    retornar _syn_modelo_cargar(ruta)\n\nfuncion cerrar_modelo(ctx: puntero) -> nulo:\n    _syn_modelo_cerrar(ctx)\n    retornar\n\n// --- Evaluaci" "\xc3" "\xb3" "n e inferencia ---\n\nfuncion evaluar(ctx: puntero, token_id: entero) -> tensor:\n    retornar _syn_modelo_evaluar(ctx, token_id)\n\nfuncion generar_token(ctx: puntero, token_id: entero,\n    temperatura: decimal, top_k: entero, top_p: decimal) -> entero:\n    retornar _syn_modelo_generar(ctx, token_id, temperatura, top_k, top_p)\n\n// --- Gesti" "\xc3" "\xb3" "n de contexto ---\n\nfuncion n_past(ctx: puntero) -> entero:\n    retornar _syn_modelo_n_past(ctx)\n\nfuncion reiniciar(ctx: puntero) -> nulo:\n    _syn_modelo_reiniciar(ctx)\n    retornar\n\nfuncion obtener_n_ctx(ctx: puntero) -> entero:\n    retornar _syn_modelo_obtener_n_ctx(ctx)\n\nfuncion establecer_n_ctx(ctx: puntero, max_tokens: entero) -> nulo:\n    _syn_modelo_establecer_n_ctx(ctx, max_tokens)\n    retornar\n\n// --- Tokenizaci" "\xc3" "\xb3" "n ---\n\nfuncion decodificar_token(ctx: puntero, token_id: entero) -> texto:\n    retornar _syn_modelo_decodificar_token(ctx, token_id)\n\nfuncion vocab_tamano(ctx: puntero) -> entero:\n    retornar _syn_modelo_vocab_tamano(ctx)\n\nfuncion codificar_contar(ctx: puntero, texto: texto) -> entero:\n    retornar _syn_modelo_codificar_contar(ctx, texto)\n\nfuncion codificar_obtener(ctx: puntero, indice: entero) -> entero:\n    retornar _syn_modelo_codificar_obtener(ctx, indice)\n\n// --- Generaci" "\xc3" "\xb3" "n de texto de alto nivel ---\n\nfuncion generar_texto(ctx: puntero, prompt: texto,\n    max_tokens: entero, temperatura: decimal,\n    top_k: entero, top_p: decimal) -> texto:\n    retornar _syn_modelo_generar_texto(ctx, prompt, max_tokens, temperatura, top_k, top_p)\n\n// --- Metadatos ---\n\nfuncion obtener_metadato(ctx: puntero, clave: texto) -> texto:\n    retornar _syn_modelo_obtener_metadato(ctx, clave)\n\nfuncion obtener_arquitectura(ctx: puntero) -> texto:\n    retornar _syn_modelo_obtener_arquitectura(ctx)\n\nfuncion obtener_n_layers(ctx: puntero) -> entero:\n    retornar _syn_modelo_obtener_n_layers(ctx)\n\nfuncion obtener_n_embd(ctx: puntero) -> entero:\n    retornar _syn_modelo_obtener_n_embd(ctx)\n\nfuncion obtener_n_heads(ctx: puntero) -> entero:\n    retornar _syn_modelo_obtener_n_heads(ctx)\n\n// ============================================================\n// Declaraciones externas de Fine-Tuning (implementadas en fine_tuning.c)\n// ============================================================\n\n// --- Ciclo de vida de sesi" "\xc3" "\xb3" "n de fine-tuning ---\nexterno funcion _syn_ft_iniciar(ctx: puntero, lr: decimal, rank: entero,\n    alpha: decimal) -> puntero\nexterno funcion _syn_ft_cerrar(sesion: puntero) -> nulo\n\n// --- Gesti" "\xc3" "\xb3" "n de adaptadores LoRA ---\nexterno funcion _syn_ft_agregar_adaptador(sesion: puntero,\n    capa_idx: entero, tipo_capa: entero, rank: entero,\n    alpha: decimal, dim_in: entero, dim_out: entero) -> entero\n\n// --- Dataset ---\nexterno funcion _syn_ft_agregar_ejemplo(sesion: puntero,\n    tokens_entrada: puntero, len_in: entero,\n    tokens_salida: puntero, len_out: entero,\n    peso: decimal) -> entero\n\n// --- Entrenamiento ---\nexterno funcion _syn_ft_paso_entrenamiento(sesion: puntero) -> decimal\nexterno funcion _syn_ft_entrenar(sesion: puntero) -> decimal\nexterno funcion _syn_ft_evaluar_perdida(sesion: puntero, len_salida: entero,\n    target_id: entero) -> decimal\n\n// --- Persistencia ---\nexterno funcion _syn_ft_guardar_pesos(sesion: puntero, ruta: texto) -> entero\nexterno funcion _syn_ft_cargar_pesos(sesion: puntero, ruta: texto) -> entero\n\n// --- Control de adaptadores ---\nexterno funcion _syn_ft_aplicar_adaptadores(sesion: puntero) -> entero\nexterno funcion _syn_ft_remover_adaptadores(sesion: puntero) -> nulo\n\n// --- Estad" "\xc3" "\xad" "sticas ---\nexterno funcion _syn_ft_obtener_perdida(sesion: puntero) -> decimal\nexterno funcion _syn_ft_obtener_paso(sesion: puntero) -> entero\n\n// ============================================================\n// Wrappers p" "\xc3" "\xba" "blicos de Fine-Tuning (Synapse idiom" "\xc3" "\xa1" "tico)\n// ============================================================\n\n// Inicia una sesi" "\xc3" "\xb3" "n de fine-tuning con la configuraci" "\xc3" "\xb3" "n dada\nfuncion ft_iniciar(ctx: puntero, lr: decimal, rank: entero, alpha: decimal) -> puntero:\n    retornar _syn_ft_iniciar(ctx, lr, rank, alpha)\n\n// Cierra una sesi" "\xc3" "\xb3" "n de fine-tuning y libera recursos\nfuncion ft_cerrar(sesion: puntero) -> nulo:\n    _syn_ft_cerrar(sesion)\n    retornar\n\n// Agrega un adaptador LoRA para una capa espec" "\xc3" "\xad" "fica\nfuncion ft_agregar_adaptador(sesion: puntero, capa_idx: entero,\n    tipo_capa: entero, rank: entero, alpha: decimal,\n    dim_in: entero, dim_out: entero) -> entero:\n    retornar _syn_ft_agregar_adaptador(sesion, capa_idx, tipo_capa,\n        rank, alpha, dim_in, dim_out)\n\n// Agrega un ejemplo al dataset de fine-tuning\nfuncion ft_agregar_ejemplo(sesion: puntero, tokens_in: puntero,\n    len_in: entero, tokens_out: puntero, len_out: entero,\n    peso: decimal) -> entero:\n    retornar _syn_ft_agregar_ejemplo(sesion, tokens_in, len_in,\n        tokens_out, len_out, peso)\n\n// Ejecuta un paso de entrenamiento\nfuncion ft_paso_entrenamiento(sesion: puntero) -> decimal:\n    retornar _syn_ft_paso_entrenamiento(sesion)\n\n// Ejecuta entrenamiento completo (todas las " "\xc3" "\xa9" "pocas)\nfuncion ft_entrenar(sesion: puntero) -> decimal:\n    retornar _syn_ft_entrenar(sesion)\n\n// Eval" "\xc3" "\xba" "a p" "\xc3" "\xa9" "rdida sin actualizar pesos\nfuncion ft_evaluar_perdida(sesion: puntero, len_salida: entero,\n    target_id: entero) -> decimal:\n    retornar _syn_ft_evaluar_perdida(sesion, len_salida, target_id)\n\n// Guarda pesos de adaptadores a archivo\nfuncion ft_guardar_pesos(sesion: puntero, ruta: texto) -> entero:\n    retornar _syn_ft_guardar_pesos(sesion, ruta)\n\n// Carga pesos de adaptadores desde archivo\nfuncion ft_cargar_pesos(sesion: puntero, ruta: texto) -> entero:\n    retornar _syn_ft_cargar_pesos(sesion, ruta)\n\n// Aplica adaptadores a la inferencia del modelo\nfuncion ft_aplicar_adaptadores(sesion: puntero) -> entero:\n    retornar _syn_ft_aplicar_adaptadores(sesion)\n\n// Remueve adaptadores (restaura modelo base)\nfuncion ft_remover_adaptadores(sesion: puntero) -> nulo:\n    _syn_ft_remover_adaptadores(sesion)\n    retornar\n\n// Obtiene la p" "\xc3" "\xa9" "rdida actual\nfuncion ft_perdida_actual(sesion: puntero) -> decimal:\n    retornar _syn_ft_obtener_perdida(sesion)\n\n// Obtiene el paso actual\nfuncion ft_paso_actual(sesion: puntero) -> entero:\n    retornar _syn_ft_obtener_paso(sesion)\n\n// ============================================================\n// Declaraciones externas de Cuantizaci" "\xc3" "\xb3" "n (implementadas en quantization.c)\n// ============================================================\n\n// --- Ciclo de vida ---\nexterno funcion _syn_qt_iniciar(formato: entero, block_size: entero) -> puntero\nexterno funcion _syn_qt_cerrar(sesion: puntero) -> nulo\n\n// --- Gesti" "\xc3" "\xb3" "n de tensores ---\nexterno funcion _syn_qt_agregar_tensor(sesion: puntero, datos: puntero,\n    filas: entero, columnas: entero, nombre: texto) -> entero\nexterno funcion _syn_qt_cuantizar_tensor(sesion: puntero, idx: entero) -> entero\nexterno funcion _syn_qt_cuantizar_todos(sesion: puntero) -> entero\n\n// --- Descuantizaci" "\xc3" "\xb3" "n ---\nexterno funcion _syn_qt_descuantizar_tensor(sesion: puntero, idx: entero) -> puntero\n\n// --- FP16 " "\xe2" "\x86" "\x94" " FP32 ---\nexterno funcion _syn_qt_fp16_a_fp32(src: puntero, dst: puntero, n: entero) -> nulo\nexterno funcion _syn_qt_fp32_a_fp16(src: puntero, dst: puntero, n: entero) -> nulo\n\n// --- Persistencia ---\nexterno funcion _syn_qt_guardar(sesion: puntero, ruta: texto) -> entero\nexterno funcion _syn_qt_cargar(sesion: puntero, ruta: texto) -> entero\n\n// --- Selecci" "\xc3" "\xb3" "n din" "\xc3" "\xa1" "mica ---\nexterno funcion _syn_qt_seleccionar_formato(ram_mb: entero) -> entero\nexterno funcion _syn_qt_estimar_tamano_modelo(params_m: entero, formato: entero) -> decimal\n\n// ============================================================\n// Wrappers p" "\xc3" "\xba" "blicos de Cuantizaci" "\xc3" "\xb3" "n (Synapse idiom" "\xc3" "\xa1" "tico)\n// ============================================================\n\n// Inicia una sesi" "\xc3" "\xb3" "n de cuantizaci" "\xc3" "\xb3" "n\nfuncion qt_iniciar(formato: entero, block_size: entero) -> puntero:\n    retornar _syn_qt_iniciar(formato, block_size)\n\n// Cierra la sesi" "\xc3" "\xb3" "n y libera recursos\nfuncion qt_cerrar(sesion: puntero) -> nulo:\n    _syn_qt_cerrar(sesion)\n    retornar\n\n// Agrega un tensor FP32 a la sesi" "\xc3" "\xb3" "n\nfuncion qt_agregar_tensor(sesion: puntero, datos: puntero,\n    filas: entero, columnas: entero, nombre: texto) -> entero:\n    retornar _syn_qt_agregar_tensor(sesion, datos, filas, columnas, nombre)\n\n// Cuantiza un tensor espec" "\xc3" "\xad" "fico\nfuncion qt_cuantizar_tensor(sesion: puntero, idx: entero) -> entero:\n    retornar _syn_qt_cuantizar_tensor(sesion, idx)\n\n// Cuantiza todos los tensores\nfuncion qt_cuantizar_todos(sesion: puntero) -> entero:\n    retornar _syn_qt_cuantizar_todos(sesion)\n\n// Descuantiza un tensor a FP32\nfuncion qt_descuantizar_tensor(sesion: puntero, idx: entero) -> puntero:\n    retornar _syn_qt_descuantizar_tensor(sesion, idx)\n\n// Convierte FP16 " "\xe2" "\x86" "\x94" " FP32\nfuncion qt_fp16_a_fp32(src: puntero, dst: puntero, n: entero) -> nulo:\n    _syn_qt_fp16_a_fp32(src, dst, n)\n    retornar\n\nfuncion qt_fp32_a_fp16(src: puntero, dst: puntero, n: entero) -> nulo:\n    _syn_qt_fp32_a_fp16(src, dst, n)\n    retornar\n\n// Guarda/Carga sesi" "\xc3" "\xb3" "n cuantizada\nfuncion qt_guardar(sesion: puntero, ruta: texto) -> entero:\n    retornar _syn_qt_guardar(sesion, ruta)\n\nfuncion qt_cargar(sesion: puntero, ruta: texto) -> entero:\n    retornar _syn_qt_cargar(sesion, ruta)\n\n// Selecciona formato " "\xc3" "\xb3" "ptimo seg" "\xc3" "\xba" "n RAM disponible\nfuncion qt_seleccionar_formato(ram_mb: entero) -> entero:\n    retornar _syn_qt_seleccionar_formato(ram_mb)\n\n// Estima tama" "\xc3" "\xb1" "o de modelo cuantizado\nfuncion qt_estimar_tamano_modelo(params_m: entero, formato: entero) -> decimal:\n    retornar _syn_qt_estimar_tamano_modelo(params_m, formato)\n\n// ============================================================\n// Funciones helper de alto nivel\n// ============================================================\n\n// argmax: retorna el " "\xc3" "\xad" "ndice del valor m" "\xc3" "\xa1" "ximo en un tensor de logits\n// Equivalente a: argmax(logits) -> token_id\nfuncion argmax(logits: tensor) -> entero:\n    inseguro:\n        asm(\"float* _d = logits.datos;\")\n        asm(\"int _n = (int)(logits.columnas);\")\n        asm(\"if (!_d || _n <= 0) return -1;\")\n        asm(\"float _max = _d[0];\")\n        asm(\"int _idx = 0;\")\n        asm(\"for (int _i = 1; _i < _n; _i++) {\")\n        asm(\"    if (_d[_i] > _max) { _max = _d[_i]; _idx = _i; }\")\n        asm(\"}\")\n        asm(\"return _idx;\")\n\n// muestra_logits: imprime los primeros N logits para depuraci" "\xc3" "\xb3" "n\nfuncion muestra_logits(logits: tensor, n: entero) -> nulo:\n    inseguro:\n        asm(\"float* _d = logits.datos;\")\n        asm(\"int _max = n < (int)logits.columnas ? n : (int)logits.columnas;\")\n        asm(\"fprintf(stderr, \\\"[Modelo] Logits (primeros %d): \\\", _max);\")\n        asm(\"for (int _i = 0; _i < _max; _i++) {\")\n        asm(\"    fprintf(stderr, \\\"%.4f \\\", _d[_i]);\")\n        asm(\"}\")\n        asm(\"fprintf(stderr, \\\"\\\\n\\\");\")\n        retornar\n\n// generar_texto_simple: genera texto con par" "\xc3" "\xa1" "metros por defecto\n// temperatura=0.7, top_k=40, top_p=0.9\nfuncion generar_texto_simple(ctx: puntero, prompt: texto,\n    max_tokens: entero) -> texto:\n    retornar _syn_modelo_generar_texto(ctx, prompt, max_tokens, 0.7, 40, 0.9)\n\n// ============================================================\n// Declaraciones externas de Destilaci" "\xc3" "\xb3" "n (implementadas en distillation.c)\n// ============================================================\n\n// --- Ciclo de vida ---\nexterno funcion _syn_kd_iniciar(temperatura: decimal, alpha: decimal,\n    vocab_size: entero) -> puntero\nexterno funcion _syn_kd_cerrar(sesion: puntero) -> nulo\n\n// --- Gesti" "\xc3" "\xb3" "n de dataset ---\nexterno funcion _syn_kd_agregar_par(sesion: puntero,\n    logits_t: puntero, logits_s: puntero,\n    target_id: entero, peso: decimal) -> entero\n\n// --- C" "\xc3" "\xb3" "mputo de p" "\xc3" "\xa9" "rdida ---\nexterno funcion _syn_kd_divergencia_kl(logits_p: puntero, logits_q: puntero,\n    n: entero, temperatura: decimal) -> decimal\nexterno funcion _syn_kd_perdida_combinada(logits_t: puntero, logits_s: puntero,\n    target_id: entero, vocab_size: entero,\n    temperatura: decimal, alpha: decimal) -> decimal\n\n// --- Destilaci" "\xc3" "\xb3" "n ---\nexterno funcion _syn_kd_paso_destilacion(sesion: puntero) -> decimal\nexterno funcion _syn_kd_destilar(sesion: puntero) -> decimal\n\n// --- Persistencia ---\nexterno funcion _syn_kd_guardar(sesion: puntero, ruta: texto) -> entero\nexterno funcion _syn_kd_cargar(sesion: puntero, ruta: texto) -> entero\n\n// --- Integraci" "\xc3" "\xb3" "n ---\nexterno funcion _syn_kd_estimar_reduccion(teacher_m: entero, student_m: entero,\n    fmt: entero) -> decimal\n\n// ============================================================\n// Wrappers p" "\xc3" "\xba" "blicos de Destilaci" "\xc3" "\xb3" "n (Synapse idiom" "\xc3" "\xa1" "tico)\n// ============================================================\n\n// Inicia una sesi" "\xc3" "\xb3" "n de destilaci" "\xc3" "\xb3" "n\nfuncion kd_iniciar(temperatura: decimal, alpha: decimal,\n    vocab_size: entero) -> puntero:\n    retornar _syn_kd_iniciar(temperatura, alpha, vocab_size)\n\n// Cierra la sesi" "\xc3" "\xb3" "n y libera recursos\nfuncion kd_cerrar(sesion: puntero) -> nulo:\n    _syn_kd_cerrar(sesion)\n    retornar\n\n// Agrega un par de logits (teacher + student) para destilaci" "\xc3" "\xb3" "n\nfuncion kd_agregar_par(sesion: puntero, logits_t: puntero,\n    logits_s: puntero, target_id: entero, peso: decimal) -> entero:\n    retornar _syn_kd_agregar_par(sesion, logits_t, logits_s, target_id, peso)\n\n// Computa la divergencia KL entre dos distribuciones\nfuncion kd_divergencia_kl(logits_p: puntero, logits_q: puntero,\n    n: entero, temperatura: decimal) -> decimal:\n    retornar _syn_kd_divergencia_kl(logits_p, logits_q, n, temperatura)\n\n// Computa la p" "\xc3" "\xa9" "rdida combinada (soft + hard) para destilaci" "\xc3" "\xb3" "n\nfuncion kd_perdida_combinada(logits_t: puntero, logits_s: puntero,\n    target_id: entero, vocab_size: entero,\n    temperatura: decimal, alpha: decimal) -> decimal:\n    retornar _syn_kd_perdida_combinada(logits_t, logits_s, target_id,\n        vocab_size, temperatura, alpha)\n\n// Ejecuta un paso de destilaci" "\xc3" "\xb3" "n sobre el dataset\nfuncion kd_paso_destilacion(sesion: puntero) -> decimal:\n    retornar _syn_kd_paso_destilacion(sesion)\n\n// Ejecuta destilaci" "\xc3" "\xb3" "n completa\nfuncion kd_destilar(sesion: puntero) -> decimal:\n    retornar _syn_kd_destilar(sesion)\n\n// Guarda el estado de destilaci" "\xc3" "\xb3" "n a archivo\nfuncion kd_guardar(sesion: puntero, ruta: texto) -> entero:\n    retornar _syn_kd_guardar(sesion, ruta)\n\n// Carga el estado de destilaci" "\xc3" "\xb3" "n desde archivo\nfuncion kd_cargar(sesion: puntero, ruta: texto) -> entero:\n    retornar _syn_kd_cargar(sesion, ruta)\n\n// Estima la reducci" "\xc3" "\xb3" "n teacher " "\xe2" "\x86" "\x92" " student con cuantizaci" "\xc3" "\xb3" "n\nfuncion kd_estimar_reduccion(teacher_m: entero, student_m: entero,\n    fmt: entero) -> decimal:\n    retornar _syn_kd_estimar_reduccion(teacher_m, student_m, fmt)\n";

static const char LIB_ORACULO[] = "#lang: es\n// std.oraculo " "\xe2" "\x80" "\x94" " Bucle del Or" "\xc3" "\xa1" "culo (Generaci" "\xc3" "\xb3" "n + Compilaci" "\xc3" "\xb3" "n + Feedback Loop)\n// Integrante de la Biblioteca Estandar de Synapse.\n//\n// Uso desde Synapse:\n//   importar std.oraculo\n//   codigo = generar_codigo(modelo, \"Escribe un hola mundo\")\n//   si codigo != \"\":\n//       // usar codigo generado\n\nimportar std.modelo\n\n// --- Constantes del Or" "\xc3" "\xa1" "culo ---\n\nconstante MAX_TOKENS_GENERAR = 256\n\nconstante SYSTEM_PROMPT = \"Eres un asistente que escribe codigo en Synapse.#10El lenguaje Synapse usa las siguientes reglas:#10- Indentacion: multiplos de 4 espacios (no tabs)#10- No uses llaves {} para bloques de control#10- Usa #lang: es al inicio del codigo#10- Los bloques se definen por indentacion#10- Usa 'funcion nombre(param: tipo) -> tipo:' para definir funciones#10- Usa 'si condicion:' para condicionales#10- Usa 'mientras condicion:' para bucles#10- Usa 'retornar expr' para valores de retorno#10- Variables: 'nombre = expr'#10- Tipos: entero, decimal, texto, booleano, puntero, tensor, nulo#10- Los strings se escriben entre comillas dobles#10- No uses punto y coma al final de lineas#10- 'verdadero' y 'falso' para booleanos#10- 'nulo' para puntero nulo\"\n\n// --- Funciones externas de compilaci" "\xc3" "\xb3" "n ---\n\nexterno funcion _syn_compilar_codigo(fuente: texto) -> entero\nexterno funcion _syn_obtener_codigo_generado() -> texto\nexterno funcion _syn_obtener_error_compilacion() -> texto\nexterno funcion _syn_obtener_linea_error() -> entero\nexterno funcion _syn_extraer_bloque_codigo(texto: texto) -> texto\nexterno funcion _syn_modelo_generar_texto(ctx: puntero, prompt: texto, max_tokens: entero, temperatura: decimal, top_k: entero, top_p: decimal) -> texto\n\n// --- Wrappers p" "\xc3" "\xba" "blicos ---\n\nfuncion compilar_codigo(fuente: texto) -> entero:\n    retornar _syn_compilar_codigo(fuente)\n\nfuncion obtener_codigo_generado() -> texto:\n    retornar _syn_obtener_codigo_generado()\n\nfuncion obtener_error_compilacion() -> texto:\n    retornar _syn_obtener_error_compilacion()\n\nfuncion obtener_linea_error() -> entero:\n    retornar _syn_obtener_linea_error()\n\nfuncion extraer_bloque_codigo(texto: texto) -> texto:\n    retornar _syn_extraer_bloque_codigo(texto)\n\nfuncion generar_texto(ctx: puntero, prompt: texto, max_tokens: entero, temperatura: decimal, top_k: entero, top_p: decimal) -> texto:\n    retornar _syn_modelo_generar_texto(ctx, prompt, max_tokens, temperatura, top_k, top_p)\n\n// --- Bucle del Or" "\xc3" "\xa1" "culo ---\n\n// Genera c" "\xc3" "\xb3" "digo Synapse a partir de una instrucci" "\xc3" "\xb3" "n usando el modelo,\n// lo compila, y si hay errores, retroalimenta al modelo para corregirlos.\n// Retorna el c" "\xc3" "\xb3" "digo fuente Synapse generado (cadena vac" "\xc3" "\xad" "a si falla tras MAX_INTENTOS).\nfuncion generar_codigo(modelo: puntero, instruccion: texto, max_intentos: entero) -> texto:\n    prompt_completo = SYSTEM_PROMPT\n    prompt_completo = concat(prompt_completo, \"#10#10Instruccion del usuario: \")\n    prompt_completo = concat(prompt_completo, instruccion)\n    prompt_completo = concat(prompt_completo, \"#10#10Genera SOLO el codigo Synapse (sin explicaciones):\")\n\n    intento = 0\n    ultimo_error = \"\"\n\n    mientras intento < max_intentos:\n        escribir_linea(concat(\"[Oraculo] Generando codigo... (Intento \", entero_a_texto(intento + 1)))\n        escribir_linea(concat(concat(concat(\"/\", entero_a_texto(max_intentos)), \")\"), \"\"))\n\n        si intento > 0:\n            prompt_completo = concat(prompt_completo, \"#10#10El compilador rechazo el codigo con el siguiente error: \")\n            prompt_completo = concat(prompt_completo, ultimo_error)\n            prompt_completo = concat(prompt_completo, \"#10#10Reescribe la funcion corrigiendo la infraccion. Genera SOLO el codigo corregido:\")\n\n        // Generar texto con el modelo\n        respuesta = generar_texto(modelo, prompt_completo, MAX_TOKENS_GENERAR, 0.7, 40, 0.9)\n\n        // Extraer bloque de c" "\xc3" "\xb3" "digo\n        codigo_generado = extraer_bloque_codigo(respuesta)\n        si codigo_generado == \"\":\n            codigo_generado = respuesta  // usar respuesta completa si no hay bloque\n\n        // Compilar el c" "\xc3" "\xb3" "digo\n        res = compilar_codigo(codigo_generado)\n\n        si res == 0:\n            escribir_linea(\"[Compilador] Exito. Binario generado.\")\n            retornar codigo_generado  // " "\xc3" "\xa9" "xito\n\n        // Capturar error para retroalimentaci" "\xc3" "\xb3" "n\n        error_msg = obtener_error_compilacion()\n        linea_err = obtener_linea_error()\n        escribir_linea(\"[Compilador] Error detectado: Re-inyectando contexto...\")\n        ultimo_error = concat(\"Linea \", entero_a_texto(linea_err))\n        ultimo_error = concat(ultimo_error, \": \")\n        ultimo_error = concat(ultimo_error, error_msg)\n\n        intento = intento + 1\n\n    escribir_linea(\"[Oraculo] Limite de intentos alcanzado.\")\n    retornar \"\"  // fallo tras max_intentos\n";
